                <div
                    className="fixed top-0 right-0 z-30 h-16 bg-slate-900/95 backdrop-blur-xl border-b border-slate-200/60 px-3 sm:px-4 lg:px-6 flex items-center justify-between gap-2 sm:gap-3 transition-all duration-200"
